  (* LPS 727298f3: [RESF] now asks that its window be mapped ([AllocRepX.ak_resf_hi]).  On the
     slow path the free-array chunk [FAB + mfa, + 262144) is the next one; [mfa] is a whole number
     of chunks below [4 * (nf + n) <= kFreeArraySize] ([NFR], [MFAA]), so the chunk lies inside
     the primary region [PRIM] maps.  [rta_s_map]'s recorded proof passes this lemma there. *)
  Lemma rta_map_mc : mfa < 4 * (nf + n) ->
    map_contains (vm_maps (m_vmmaps mo)) (Z_to_bv 64 (FAB + mfa)) (Z_to_bv 64 262144) = true.
  Proof.
    intros SLOW.
    assert (U : forall z, 0 <= z < 2 ^ 64 -> bv_unsigned (Z_to_bv 64 z) = z)
      by (intros z Hz; rewrite Z_to_bv_unsigned; apply bv_wrap_small; unfold bv_modulus; exact Hz).
    pose proof SBR as S1. pose proof HC as H1. pose proof NFR as N1. pose proof MFAA as M1.
    destruct M1 as [M1]. destruct N1 as (N1a & N1b & N1c & N1d).
    assert (B : AHI_LO <= sb /\ sb + 2 ^ 37 + 4096 <= aceil /\ 1 <= c < 32 /\ 0 <= mfa /\ mfa + 262144 <= 536870912)
      by (clear - S1 H1 N1a N1b N1c N1d M1 SLOW; unfold kSpaceSize, kPageSize, kFreeArraySize, kFreeArrayMapSize, kNumClasses in *;
          Z.div_mod_to_equations; lia).
    clear - PRIM B U. pose proof aceil_facts as AF.
    apply PRIM; unfold FAB, rbeg, kFreeArrayOffset; rewrite !U; unfold AHI_LO in *; lia.
  Qed.

  (* [comment removed for export] *)
  Lemma rta_s_map : forall msF1 mo1, mfa < 4 * (nf + n) ->
    rta1_at L S Zr mo ra sp gp tp a1 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c R rbeg FAB CH TH TSD CTX sb ARI nf n mfa au mu fl ws msF1 mo1 ->
    (forall msF' mo', rta2_at L S Zr mo ra sp gp tp a1 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c R rbeg FAB CH TH TSD CTX sb ARI nf n mfa au mu (mfa + 262144) fl ws msF' mo' ->
                      sreach asegs Q (mkCfg msF' mo')) ->
    sreach asegs Q (mkCfg msF1 mo1).
